<?php
declare(strict_types=1);require dirname(__DIR__).'/bootstrap.php';use FMonitor2\InstallationProcess\{ChecklistTemplateSchemaMigration,MariaDbPilotSnapshotImporter,ObjectDetailSnapshotSchemaMigration,ProductionProcessSchemaMigration,PilotLegacyObjectSchemaMigration};
$h=getenv('FMONITOR_TEST_DB_HOST')?:'127.0.0.1';$port=(int)(getenv('FMONITOR_TEST_DB_PORT')?:23306);$u=getenv('FMONITOR_TEST_DB_ADMIN_USER')?:'root';$pw=getenv('FMONITOR_TEST_DB_ADMIN_PASSWORD')?:'fmonitor2_test_root_local';$name='t_snapshot_'.bin2hex(random_bytes(4));$a=new mysqli($h,$u,$pw,'',$port);$a->query("CREATE DATABASE `$name` DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");$db=new mysqli($h,$u,$pw,$name,$port);$p='snap_';$l='legacy_';$file=tempnam(sys_get_temp_dir(),'snapshot-');
try{ProductionProcessSchemaMigration::apply($db,$p);ObjectDetailSnapshotSchemaMigration::apply($db,$p);ChecklistTemplateSchemaMigration::apply($db,$p);PilotLegacyObjectSchemaMigration::apply($db,$l);$defs=[];for($i=1;$i<=42;$i++)$defs[]=['id'=>$i,'part_id'=>1,'name'=>'Item '.$i,'share'=>$i===42?15:($i===1?45:1),'rang'=>$i,'needphoto'=>0];$payload=['snapshotVersion'=>'v','capturedAt'=>'2026-09-07 12:00:00','validFrom'=>'2026-09-07 12:00:00','validity'=>'x','source'=>'synthetic','parts'=>array_map(fn($i)=>['id'=>$i,'name'=>'P'.$i,'rang'=>$i],range(1,8)),'definitions'=>$defs];$template=['payload'=>$payload,'contentSha256'=>hash('sha256',json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR)),'counts'=>['parts'=>8,'definitions'=>42,'totalShare'=>100]];$tech=[];foreach(['floors','weight','speed','pittype','pitmaterial','paired']as$k)$tech[$k]=['raw'=>'1','display'=>'One'];$object=['id'=>7,'address'=>'Address','entrance'=>'1','registrationNumber'=>'R-7','plannedDates'=>['start'=>null,'adjustedStart'=>null,'adjustedFinish'=>null,'plannedFinish'=>null,'legacyFinish'=>null],'technical'=>$tech,'controlEngineerUserId'=>null,'eligibilityProof'=>['actualOpening'=>false,'checklistActivity'=>false]];$snapshot=['schemaVersion'=>'manual-pilot-source-snapshot-v1','capturedAtUtc'=>'2026-09-07T12:00:00Z','eligibility'=>['plannedDateFilter'=>null],'objects'=>[$object],'checklistTemplate'=>$template];file_put_contents($file,json_encode($snapshot,JSON_THROW_ON_ERROR));chmod($file,0600);$sha=hash_file('sha256',$file);$owner=new MariaDbPilotSnapshotImporter($db,$p,$l);$one=$owner->import($file,$sha,'2026-09-07T12:00:00Z');assertSameValue([1,1,true],[count($one['cases']['imported']),$one['details']['created'],$one['template']['created']],'first import creates case detail template');$two=$owner->import($file,$sha,'2026-09-07T12:01:00Z');assertSameValue([1,1,false],[count($two['cases']['alreadyPresent']),$two['details']['present'],$two['template']['created']],'repeat is no-op');assertSameValue(0,(int)$db->query("SELECT COUNT(*)n FROM `{$p}fm2_checklist_template_associations`")->fetch_assoc()['n'],'import does not bind template');echo"pilot_snapshot_import_manual_test: PASS\n";}finally{@unlink($file);$db->close();$a->query("DROP DATABASE IF EXISTS `$name`");$a->close();}
